<script>
const people=[{id:1,code:'EMP001',name:'Sample Employee A'},{id:2,code:'EMP002',name:'Sample Employee B'}];
const review=window.PayrollImportUI.mount({records:()=>[],postRun:async()=>{throw Error('Posting is disabled in this preview.');},employees:people,config:{frequency:'monthly'}});
document.getElementById('sample-payroll-open').addEventListener('click',()=>review.open());
document.getElementById('sample-payroll-download').addEventListener('click',()=>{const headers=window.PayrollImport.headers;const rows=people.map((person,index)=>{const row={pay_date:'2026-10-30',run_name:'Sample monthly payroll',period_start:'2026-10-01',period_end:'2026-10-31',employee:person.name,employee_code:person.code,pay_type:'Taxable',...Object.fromEntries(window.PayrollRegister.amountFields.map(field=>[field,'0.00'])),basic:'30000.00',sssEe:'1500.00',phicEe:'750.00',hdmfEe:'200.00',withholding:index?'1200.00':'1000.00',review_basis:'regular'};return headers.map(key=>row[key]||'').join(',');});const url=URL.createObjectURL(new Blob(['\uFEFF'+headers.join(',')+'\r\n'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='sample-client-payroll.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
</script></body></html>
